    test("source_events (1)", async () => {
        const server = mockServerPool.createServer();
        const client = new HiddenLayerClient({ maxRetries: 0, token: "test", environment: server.baseUrl });

        const rawResponseBody = {
            first: "first",
            prev: "prev",
            next: "next",
            last: "last",
            items: [
                {
                    source_event_id: "source_event_id",
                    source: "RUNTIME",
                    reference: { type: "RUNTIME_SESSION", session_id: "session_id" },
                    correlated_at: "2024-01-15T09:30:00Z",
                },
            ],
        };

        server
            .mockEndpoint({ once: false })
            .get("/triage/v1/issues/TRI-1042/source-events")
            .respondWith()
            .statusCode(200)
            .jsonBody(rawResponseBody)
            .build();

        const expected = rawResponseBody;
        const page = await client.triage.issues.sourceEvents({
            issue_id: "TRI-1042",
            limit: 50,
        });

        expect(expected.items).toEqual(page.data);
        expect(page.hasNextPage()).toBe(true);
        const nextPage = await page.getNextPage();
        expect(expected.items).toEqual(nextPage.data);
    });

